import bisect, hashlib

def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16) % (2**32)

class Ring:
    """Consistent hash ring with virtual nodes."""
    def __init__(self, nodes, vnodes=100):
        self.vnodes = vnodes
        self.ring = []                    # sorted (hash, node) points
        for n in nodes:
            self.add(n)

    def add(self, node):
        for i in range(self.vnodes):
            bisect.insort(self.ring, (h(f"{node}#{i}"), node))

    def owner(self, key):
        hashes = [p[0] for p in self.ring]
        i = bisect.bisect_right(hashes, h(key)) % len(self.ring)
        return self.ring[i][1]            # first node clockwise

keys = [f"user:{i}" for i in range(10_000)]
ring = Ring(["A", "B", "C"])
before = {k: ring.owner(k) for k in keys}

ring.add("D")                             # scale out: 3 -> 4 nodes
moved = sum(1 for k in keys if ring.owner(k) != before[k])
frac = moved / len(keys)

# consistent hashing: ~1/4 of keys move; mod-N would move ~3/4
assert 0.15 < frac < 0.35, frac
print(f"adding node D moved {frac:.0%} of keys (mod-N remap would move ~75%)")
